"""Final synthetic DGP for OpFlow."""

from __future__ import annotations

from dataclasses import dataclass

import numpy as np
import pandas as pd

from opflow_experiments.data.splits import build_env_splits
from opflow_experiments.utils.seed import set_seed


DGP_REGIME = "DGP"


@dataclass
class DGPData:
    """Synthetic OD bundle generated by the final DGP."""

    records: pd.DataFrame
    env_meta: pd.DataFrame
    origins: np.ndarray
    destinations: np.ndarray
    candidate_indices: np.ndarray
    candidate_mask: np.ndarray
    metadata: dict


def safe_corr(a: np.ndarray, b: np.ndarray) -> float:
    a = np.asarray(a, dtype=float).reshape(-1)
    b = np.asarray(b, dtype=float).reshape(-1)
    valid = np.isfinite(a) & np.isfinite(b)
    a = a[valid]
    b = b[valid]
    if len(a) < 2 or np.isclose(a.std(), 0.0) or np.isclose(b.std(), 0.0):
        return float("nan")
    return float(np.corrcoef(a, b)[0, 1])


def _cfg(config: dict) -> dict:
    return config.get("dgp", {})


def _get(config: dict, key: str, default):
    dgp = _cfg(config)
    return dgp.get(key, config.get(key, default))


def row_center_masked(values: np.ndarray, mask: np.ndarray) -> np.ndarray:
    values = np.asarray(values, dtype=float)
    mask = np.asarray(mask, dtype=bool)
    out = np.zeros_like(values, dtype=float)
    for row_idx in range(values.shape[0]):
        valid = mask[row_idx]
        if valid.any():
            row = values[row_idx, valid]
            out[row_idx, valid] = row - row.mean()
    return out


def row_softmax_masked(scores: np.ndarray, mask: np.ndarray, tau: float) -> np.ndarray:
    scores = np.asarray(scores, dtype=float)
    mask = np.asarray(mask, dtype=bool)
    out = np.zeros_like(scores, dtype=float)
    for row_idx in range(scores.shape[0]):
        valid = mask[row_idx]
        if not valid.any():
            continue
        row = scores[row_idx, valid]
        shifted = row - row.max()
        exp = np.exp(shifted / max(float(tau), 1e-8))
        out[row_idx, valid] = exp / np.maximum(exp.sum(), 1e-12)
    return out


def rank_prefix_exposure(opportunity_rows: np.ndarray, cost_rows: np.ndarray) -> tuple[np.ndarray, np.ndarray]:
    """Hard rank-prefix exposure excluding destination j itself."""
    opportunity_rows = np.asarray(opportunity_rows, dtype=float)
    cost_rows = np.asarray(cost_rows, dtype=float)
    one_dim = opportunity_rows.ndim == 1
    if one_dim:
        opportunity_rows = opportunity_rows[None, :]
        cost_rows = cost_rows[None, :]
    exposure = np.zeros_like(opportunity_rows, dtype=float)
    ranks = np.zeros_like(opportunity_rows, dtype=int)
    for row_idx in range(opportunity_rows.shape[0]):
        order = np.argsort(cost_rows[row_idx], kind="mergesort")
        sorted_opp = opportunity_rows[row_idx, order]
        prefix = np.cumsum(sorted_opp) - sorted_opp
        inv_order = np.empty_like(order)
        inv_order[order] = np.arange(len(order))
        exposure[row_idx] = prefix[inv_order]
        ranks[row_idx] = inv_order
    if one_dim:
        return exposure[0], ranks[0]
    return exposure, ranks


def local_competition(destinations: np.ndarray, opportunity: np.ndarray, omega: float) -> np.ndarray:
    """Destination-side local opportunity aggregate excluding self."""
    dist = np.linalg.norm(destinations[:, None, :] - destinations[None, :, :], axis=2)
    weights = np.exp(-dist / max(float(omega), 1e-8))
    np.fill_diagonal(weights, 0.0)
    return weights @ np.asarray(opportunity, dtype=float)


def _opportunity_field(rng: np.random.Generator, destinations: np.ndarray, cfg: dict) -> np.ndarray:
    n_centers = int(rng.integers(int(cfg.get("num_centers_min", 3)), int(cfg.get("num_centers_max", 5)) + 1))
    centers = rng.uniform(0.0, 1.0, size=(n_centers, 2))
    weights = rng.dirichlet(np.ones(n_centers))
    bandwidth = rng.uniform(float(cfg.get("bandwidth_min", 0.08)), float(cfg.get("bandwidth_max", 0.18)), size=n_centers)
    background = float(cfg.get("opportunity_background", 0.08))
    sq_dist = ((destinations[:, None, :] - centers[None, :, :]) ** 2).sum(axis=2)
    raw = background + (weights[None, :] * np.exp(-sq_dist / (2.0 * bandwidth[None, :] ** 2))).sum(axis=1)
    raw = np.maximum(raw / np.maximum(raw.mean(), 1e-12), float(cfg.get("eps", 1e-6)))
    return raw / np.maximum(raw.mean(), 1e-12)


def _fit_standardizer(components: dict[str, list[np.ndarray]], eps: float) -> dict[str, dict[str, float]]:
    stats: dict[str, dict[str, float]] = {}
    for key, arrays in components.items():
        values = np.concatenate([np.asarray(arr, dtype=float).reshape(-1) for arr in arrays])
        stats[key] = {
            "mean": float(values.mean()),
            "std": float(values.std(ddof=0) + eps),
        }
    return stats


def _standardize(values: np.ndarray, stats: dict[str, float]) -> np.ndarray:
    return (np.asarray(values, dtype=float) - stats["mean"]) / stats["std"]


def _row_standardize(values: np.ndarray) -> np.ndarray:
    values = np.asarray(values, dtype=float)
    return (values - values.mean()) / (values.std(ddof=0) + 1e-8)


def _build_candidates(rng: np.random.Generator, cost_full: np.ndarray, cfg: dict) -> tuple[list[np.ndarray], np.ndarray, np.ndarray, np.ndarray]:
    n_o, n_d = cost_full.shape
    k_mean = float(cfg.get("K_mean", 25))
    k_std = float(cfg.get("K_std", 5))
    k_min = int(cfg.get("K_min", 15))
    k_max = min(int(cfg.get("K_max", 40)), n_d)
    sizes = np.clip(np.rint(rng.normal(k_mean, k_std, size=n_o)).astype(int), k_min, k_max)
    candidate_lists = [np.argsort(cost_full[i], kind="mergesort")[: sizes[i]] for i in range(n_o)]
    candidate_indices = np.full((n_o, k_max), -1, dtype=int)
    candidate_mask = np.zeros((n_o, k_max), dtype=bool)
    for origin_id, candidates in enumerate(candidate_lists):
        k_i = len(candidates)
        candidate_indices[origin_id, :k_i] = candidates
        candidate_mask[origin_id, :k_i] = True
    return candidate_lists, sizes, candidate_indices, candidate_mask


def _prepare_env_components(
    rng: np.random.Generator,
    env_id: int,
    env_index: int,
    split: str,
    origins: np.ndarray,
    destinations: np.ndarray,
    cost_full: np.ndarray,
    candidate_lists: list[np.ndarray],
    candidate_sizes: np.ndarray,
    cfg: dict,
) -> dict:
    eps = float(cfg.get("eps", 1e-6))
    opportunity = _opportunity_field(rng, destinations, cfg)
    ell_dest = local_competition(destinations, opportunity, float(cfg.get("omega", 0.15)))
    proxy = np.exp(np.log(opportunity + eps) + float(cfg.get("sigma_proxy", 0.35)) * rng.normal(0.0, 1.0, size=len(destinations)))
    proxy = np.maximum(proxy / np.maximum(proxy.mean(), eps), eps)
    rows = []
    raw_components = {"log_o": [], "log_s": [], "log_l": [], "cost": []}
    prefix_self_error = 0.0
    for origin_id, candidates in enumerate(candidate_lists):
        cost = cost_full[origin_id, candidates]
        opp = opportunity[candidates]
        ell = ell_dest[candidates]
        exposure, ranks = rank_prefix_exposure(opp, cost)
        sorted_opp = opp[np.argsort(cost, kind="mergesort")]
        expected_prefix = np.cumsum(sorted_opp) - sorted_opp
        sorted_exposure = exposure[np.argsort(cost, kind="mergesort")]
        prefix_self_error = max(prefix_self_error, float(np.max(np.abs(sorted_exposure - expected_prefix))))
        raw_components["log_o"].append(np.log1p(opp))
        raw_components["log_s"].append(np.log1p(exposure))
        raw_components["log_l"].append(np.log1p(ell))
        raw_components["cost"].append(cost)
        rows.append(
            {
                "origin_id": origin_id,
                "candidates": candidates,
                "cost": cost,
                "opportunity": opp,
                "ell": ell,
                "exposure": exposure,
                "ranks": ranks,
                "proxy": proxy[candidates],
                "k_i": int(candidate_sizes[origin_id]),
            }
        )
    return {
        "env_id": env_id,
        "env_index": env_index,
        "split": split,
        "opportunity": opportunity,
        "ell_dest": ell_dest,
        "proxy": proxy,
        "rows": rows,
        "raw_components": raw_components,
        "prefix_self_error": prefix_self_error,
    }


def generate_dgp_data(config: dict, seed: int) -> DGPData:
    """Generate one synthetic dataset from the final DGP."""
    cfg = _cfg(config)
    rng = set_seed(seed)
    n_o = int(_get(config, "N_o", 80))
    n_d = int(_get(config, "N_d", 80))
    tau = float(_get(config, "tau", 0.7))
    eps = float(cfg.get("eps", 1e-6))
    splits = build_env_splits(
        int(cfg.get("num_train_env", cfg.get("num_env_train", 8))),
        int(cfg.get("num_val_env", cfg.get("num_env_val", 2))),
        int(cfg.get("num_test_env", cfg.get("num_env_test", 4))),
    )
    env_ids = splits["train"] + splits["val"] + splits["test"]
    split_by_env = {env: split for split, ids in splits.items() for env in ids}

    origins = rng.uniform(0.0, 1.0, size=(n_o, 2))
    destinations = rng.uniform(0.0, 1.0, size=(n_d, 2))
    cost_full = np.linalg.norm(origins[:, None, :] - destinations[None, :, :], axis=2)
    candidate_lists, candidate_sizes, candidate_indices, candidate_mask = _build_candidates(rng, cost_full, cfg)

    env_components = []
    train_raw = {"log_o": [], "log_s": [], "log_l": [], "cost": []}
    for env_index, env_id in enumerate(env_ids):
        split = split_by_env[env_id]
        env = _prepare_env_components(
            rng,
            env_id,
            env_index,
            split,
            origins,
            destinations,
            cost_full,
            candidate_lists,
            candidate_sizes,
            cfg,
        )
        env_components.append(env)
        if split == "train":
            for key, values in env["raw_components"].items():
                train_raw[key].extend(values)
    standardizer = _fit_standardizer(train_raw, eps=eps)
    train_cost_values = np.concatenate(train_raw["cost"])
    median_train_cost = float(np.median(train_cost_values) + eps)

    params = {
        "beta_o": float(cfg.get("beta_o", 1.15)),
        "beta_c": float(cfg.get("beta_c", 0.35)),
        "beta_s": float(cfg.get("beta_s", 0.65)),
        "beta_l": float(cfg.get("beta_l", 0.45)),
        "beta_oc": float(cfg.get("beta_oc", 0.25)),
        "gamma_o": float(cfg.get("gamma_o", 0.25)),
        "gamma_c": float(cfg.get("gamma_c", 0.25)),
        "phi_scale": float(cfg.get("phi_scale", 0.7)),
        "sigma_delta": float(cfg.get("sigma_delta", 0.03)),
    }
    scale_base = float(cfg.get("scale_base", 4.4))
    origin_scale_x = float(cfg.get("origin_scale_x", 0.9))
    origin_scale_y = float(cfg.get("origin_scale_y", 0.5))
    env_scale_shift_std = float(cfg.get("env_scale_shift_std", 0.15))
    scale_noise_std = float(cfg.get("scale_noise_std", 0.18))
    rho_by_split = {
        "train": float(cfg.get("shortcut_rho_train", 0.9)),
        "val": float(cfg.get("shortcut_rho_val", 0.4)),
        "test": float(cfg.get("shortcut_rho_test", 0.1)),
    }
    eta_by_split = {
        "train": float(cfg.get("shortcut_eta_train", 0.8)),
        "val": float(cfg.get("shortcut_eta_val", 0.4)),
        "test": float(cfg.get("shortcut_eta_test", 0.2)),
    }

    all_frames: list[pd.DataFrame] = []
    meta_rows: list[dict] = []
    opportunity_by_env = []
    prefix_self_max = 0.0
    for env in env_components:
        env_id = env["env_id"]
        env_index = env["env_index"]
        split = env["split"]
        prefix_self_max = max(prefix_self_max, float(env["prefix_self_error"]))
        env_shift = rng.normal(0.0, env_scale_shift_std)
        log_r = (
            scale_base
            + origin_scale_x * origins[:, 0]
            - origin_scale_y * origins[:, 1]
            + env_shift
            + rng.normal(0.0, scale_noise_std, size=n_o)
        )
        log_r_z = (log_r - log_r.mean()) / (log_r.std(ddof=0) + eps)
        r_oracle = np.exp(log_r)
        rows = []
        rho_e = np.clip(rho_by_split.get(split, 0.0), -0.999, 0.999)
        eta_e = np.clip(eta_by_split.get(split, 0.0), -0.999, 0.999)
        for row in env["rows"]:
            origin_id = int(row["origin_id"])
            candidates = row["candidates"]
            cost = row["cost"]
            opp = row["opportunity"]
            exposure = row["exposure"]
            ell = row["ell"]
            ranks = row["ranks"]
            proxy = row["proxy"]
            k_i = int(row["k_i"])
            z_log_o = _standardize(np.log1p(opp), standardizer["log_o"])
            z_log_s = _standardize(np.log1p(exposure), standardizer["log_s"])
            z_log_l = _standardize(np.log1p(ell), standardizer["log_l"])
            z_c = _standardize(cost, standardizer["cost"])
            x_i = float(origins[origin_id, 0])
            y_i = float(origins[origin_id, 1])
            beta_o_i = params["beta_o"] * (1.0 + params["gamma_o"] * (2.0 * y_i - 1.0))
            beta_c_i = params["beta_c"] * (1.0 + params["gamma_c"] * (2.0 * x_i - 1.0))
            c_decay = cost / median_train_cost
            delta = rng.normal(0.0, params["sigma_delta"], size=k_i)
            delta = delta - delta.mean()
            g = (
                beta_o_i * z_log_o
                - beta_c_i * z_c
                - params["beta_s"] * z_log_s
                + params["beta_l"] * z_log_l
                + params["beta_oc"] * z_log_o * np.exp(-c_decay / max(params["phi_scale"], eps))
                + delta
            )
            psi = g - g.mean()
            pi = row_softmax_masked(psi[None, :], np.ones((1, k_i), dtype=bool), tau=tau)[0]
            lam = r_oracle[origin_id] * pi
            y_obs = rng.poisson(lam) if bool(cfg.get("poisson", True)) else lam
            score_z = _row_standardize(psi)
            x_res_0 = rho_e * score_z + np.sqrt(max(1.0 - rho_e**2, 0.0)) * rng.normal(0.0, 1.0, size=k_i)
            x_res_1 = eta_e * log_r_z[origin_id] + np.sqrt(max(1.0 - eta_e**2, 0.0)) * rng.normal(0.0, 1.0, size=k_i)
            rank_frac = ranks / max(k_i - 1, 1)
            row_cost_z = _row_standardize(cost)
            dest = destinations[candidates]
            dx = dest[:, 0] - origins[origin_id, 0]
            dy = dest[:, 1] - origins[origin_id, 1]
            rows.append(
                pd.DataFrame(
                    {
                        "env_id": env_id,
                        "env_index": env_index,
                        "split": split,
                        "regime": DGP_REGIME,
                        "origin_id": origin_id,
                        "dest_id": candidates,
                        "candidate_slot": np.arange(k_i),
                        "candidate_mask": True,
                        "k_i": k_i,
                        "x_origin_0": origins[origin_id, 0],
                        "x_origin_1": origins[origin_id, 1],
                        "x_geo_0": dest[:, 0],
                        "x_geo_1": dest[:, 1],
                        "x_geo_2": rank_frac,
                        "x_geo_3": proxy,
                        "x_geo_4": row_cost_z,
                        "cost": cost,
                        "distance": cost,
                        "dx": dx,
                        "dy": dy,
                        "cost_rank_frac": rank_frac,
                        "row_standardized_cost": row_cost_z,
                        "opp_proxy": proxy,
                        "o_true": opp,
                        "s_true": exposure,
                        "ell_true": ell,
                        "g_oracle": g,
                        "psi_oracle": psi,
                        "pi_oracle": pi,
                        "R_oracle": r_oracle[origin_id],
                        "lambda_oracle": lam,
                        "y_obs": y_obs,
                        "x_res_0": x_res_0,
                        "x_res_1": x_res_1,
                        "shortcut_history": x_res_0,
                    }
                )
            )
        frame = pd.concat(rows, ignore_index=True)
        all_frames.append(frame)
        opportunity_by_env.append(env["opportunity"])
        row_totals = frame.groupby("origin_id", sort=False)["y_obs"].sum()
        entropy = frame.assign(_term=-(frame["pi_oracle"] * np.log(np.maximum(frame["pi_oracle"], eps)))).groupby("origin_id")["_term"].sum()
        meta_rows.append(
            {
                "env_id": env_id,
                "env_index": env_index,
                "split": split,
                "N_o": n_o,
                "N_d": n_d,
                "K_mean": float(candidate_sizes.mean()),
                "K_std": float(candidate_sizes.std(ddof=0)),
                "K_min": int(candidate_sizes.min()),
                "K_max": int(candidate_sizes.max()),
                "opportunity_mean": float(env["opportunity"].mean()),
                "opportunity_std": float(env["opportunity"].std(ddof=0)),
                "proxy_true_opp_corr": safe_corr(env["proxy"], env["opportunity"]),
                "shortcut_psi_corr": safe_corr(frame["x_res_0"], frame["psi_oracle"]),
                "prefix_self_exclusion_max_abs_error": prefix_self_max,
                "psi_oracle_row_mean_abs": float(frame.groupby("origin_id")["psi_oracle"].mean().abs().mean()),
                "pi_oracle_row_sum_error": float(np.max(np.abs(frame.groupby("origin_id")["pi_oracle"].sum().to_numpy(dtype=float) - 1.0))),
                "lambda_identity_max_abs_error": float(np.max(np.abs(frame["lambda_oracle"].to_numpy(dtype=float) - frame["R_oracle"].to_numpy(dtype=float) * frame["pi_oracle"].to_numpy(dtype=float)))),
                "row_total_mean": float(row_totals.mean()),
                "row_total_std": float(row_totals.std(ddof=0)),
                "zero_count_ratio": float((frame["y_obs"].to_numpy(dtype=float) == 0.0).mean()),
                "allocation_entropy_mean": float(entropy.mean()),
                "effective_destinations_mean": float(np.exp(entropy).mean()),
                "standardizer_fit_split": "train",
                "median_train_cost": median_train_cost,
            }
        )

    records = pd.concat(all_frames, ignore_index=True)
    row_sums = records.groupby(["env_id", "origin_id"], sort=False)["pi_oracle"].sum().to_numpy(dtype=float)
    if not np.allclose(row_sums, 1.0, atol=1e-6):
        raise AssertionError("Each oracle allocation row must sum to one over valid candidates.")
    opp_corr = np.corrcoef(np.vstack(opportunity_by_env))
    upper = opp_corr[np.triu_indices_from(opp_corr, k=1)]
    metadata = {
        "seed": seed,
        "regime": DGP_REGIME,
        "splits": splits,
        "N_o": n_o,
        "N_d": n_d,
        "candidate_sizes": candidate_sizes.tolist(),
        "candidate_size_mean": float(candidate_sizes.mean()),
        "candidate_size_std": float(candidate_sizes.std(ddof=0)),
        "prefix_self_exclusion_max_abs_error": prefix_self_max,
        "standardizer": standardizer,
        "standardizer_fit_split": "train",
        "median_train_cost": median_train_cost,
        "opportunity_env_corr_mean": float(np.nanmean(upper)) if len(upper) else float("nan"),
        "opportunity_env_corr_max": float(np.nanmax(upper)) if len(upper) else float("nan"),
        "mechanism_params": params,
        "config": cfg,
    }
    return DGPData(
        records=records,
        env_meta=pd.DataFrame(meta_rows),
        origins=origins,
        destinations=destinations,
        candidate_indices=candidate_indices,
        candidate_mask=candidate_mask,
        metadata=metadata,
    )


def build_opportunity_intervention(records: pd.DataFrame, config: dict, delta: float = 0.25) -> pd.DataFrame:
    """Compatibility hook for diagnostics that do not run by default for DGP."""
    return records.copy()
